using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Web.Script.Serialization;
using LocalFlow;

public static class PolishProbe {
    [STAThread]public static void Main(string[] args){Dictionary<string,object> report=new Dictionary<string,object>();try{Dictionary<string,string> connection=new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(File.ReadAllText(args[0]));using(Models models=new Models(Path.GetDirectoryName(args[0]))){typeof(Models).GetField("rewriteUrl",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(models,connection["url"]);typeof(Models).GetField("token",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(models,connection["token"]);Action<bool,string> check=(ok,name)=>{report[name]=ok;Console.WriteLine((ok?"PASS ":"FAIL ")+name);if(!ok)throw new Exception(name);};if(args.Length>2&&args[2]=="retry")PolishRetryChecks.Run(models,check).GetAwaiter().GetResult();else if(args.Length>2&&args[2]=="formats")PolishChecks.Formats(models,check,report).GetAwaiter().GetResult();else if(args.Length>2&&args[2]=="prose")PolishChecks.Prose(models,check,report).GetAwaiter().GetResult();else if(args.Length>2&&args[2]=="tables")QualityChecks.Run(models,check,report,"table").GetAwaiter().GetResult();else if(args.Length>2&&args[2]=="selected")QualityChecks.Run(models,check,report,"selected").GetAwaiter().GetResult();else if(args.Length>2&&args[2]=="outlines")QualityChecks.Run(models,check,report,"outline").GetAwaiter().GetResult();else if(args.Length>2&&args[2]=="quality")QualityChecks.Run(models,check,report).GetAwaiter().GetResult();else if(args.Length>2&&args[2]=="faq")PolishChecks.Faq(models,check,report).GetAwaiter().GetResult();else if(args.Length>2&&args[2]=="tokens")PolishChecks.Tokens(models,check,report).GetAwaiter().GetResult();else if(args.Length>2&&args[2]=="routes")PolishChecks.Routes(models,check,report).GetAwaiter().GetResult();else PolishChecks.Run(models,check,report).GetAwaiter().GetResult();report["complete"]=true;}}catch(Exception error){report["complete"]=false;report["error"]=error.ToString();Console.WriteLine(error);Environment.ExitCode=1;}finally{File.WriteAllText(args[1],new JavaScriptSerializer().Serialize(report));}}
}
